using System; using System.Collections.Generic; using System.Text.Json; enum Rol { Estudiante, Gerente } class Program { static void Main() { var opts = new JsonSerializerOptions { Converters = { new System.Text.Json.Serialization.JsonStringEnumConverter() } }; var str = JsonSerializer.Serialize(new List<Rol> { Rol.Gerente }, opts); Console.WriteLine(str); var roles = JsonSerializer.Deserialize<List<Rol>>(str, opts); Console.WriteLine(roles[0]); } }
